// Package example holds models used to test the generated query sets; its generated file is committed and checked
// for freshness by the generator's tests.
package example

import (
	"database/sql"
	"time"
)

type Stage string

type Coordinates struct{ Lat, Lng float64 }

// gen:qs
//
//go:generate go run github.com/anvh2/go-kit/cmd/goqueryset -in models.go -out autogenerated_models.gen.go
type Plot struct {
	ID          uint64         `gorm:"column:id;primaryKey"`
	FarmID      uint64         `gorm:"column:farm_id"`
	Code        string         `gorm:"column:code"`
	Stage       Stage          `gorm:"column:stage"`
	AreaM2      float64        // default column name (area_m2)
	Active      bool           `gorm:"column:active"`
	RetiredAt   *time.Time     `gorm:"column:retired_at"`
	Note        sql.NullString `gorm:"column:note"`
	CreatedAt   time.Time      `gorm:"column:created_at"`
	Location    Coordinates    `gorm:"serializer:json"` // composite value: no query methods
	Plantings   []Planting     `gorm:"foreignKey:PlotID"`
	Cached      string         `gorm:"-"`
	unexported  int
	order, user string // unexported, ignored
}

func (Plot) TableName() string { return "plots" }

// gen:qs
type Planting struct {
	ID     uint64 `gorm:"column:id;primaryKey"`
	PlotID uint64 `gorm:"column:plot_id"`
	Crop   string `gorm:"column:crop"`
}

func (Planting) TableName() string { return "plantings" }
